-- =============================================================================
-- V30 — DoorDrop notification event catalog
-- Real event-to-template routing for auth, shipments, billing, marketplace and support.
-- =============================================================================

ALTER TABLE email_templates
  MODIFY category ENUM('auth','shipments','billing','omnichannel','marketplace') NOT NULL DEFAULT 'auth';

ALTER TABLE email_logs
  ADD COLUMN entity_type VARCHAR(50) NULL AFTER shipment_id,
  ADD COLUMN entity_id VARCHAR(191) NULL AFTER entity_type,
  ADD COLUMN audience VARCHAR(40) NULL AFTER entity_id,
  ADD COLUMN template_id VARCHAR(80) NULL AFTER audience,
  ADD INDEX idx_email_logs_entity (entity_type, entity_id, event_code, audience, status),
  ADD UNIQUE KEY uq_email_entity_event_audience (entity_type, entity_id, event_code, audience, to_email);

CREATE TABLE IF NOT EXISTS email_notification_events (
  event_code VARCHAR(100) PRIMARY KEY,
  template_id VARCHAR(80) NOT NULL,
  category ENUM('auth','shipments','billing','omnichannel','marketplace') NOT NULL,
  label VARCHAR(150) NOT NULL,
  description VARCHAR(500) NULL,
  audience VARCHAR(40) NOT NULL DEFAULT 'customer',
  is_enabled TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_email_event_template FOREIGN KEY (template_id) REFERENCES email_templates(id) ON DELETE RESTRICT,
  INDEX idx_email_events_category (category, is_enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE
  category = VALUES(category), name = VALUES(name), description = VALUES(description), variables_json = VALUES(variables_json);

ON DUPLICATE KEY UPDATE subject=VALUES(subject), preheader=VALUES(preheader), body_html=VALUES(body_html), body_text=VALUES(body_text), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE
  template_id=VALUES(template_id), category=VALUES(category), label=VALUES(label), description=VALUES(description), audience=VALUES(audience);
